// vbaLexerInit initializes any static state used to implement vbaLexer. By default the
// static state used to implement the lexer is lazily initialized during the first call to
// NewvbaLexer(). You can call this function if you wish to initialize the static state ahead
// of time.
func VbaLexerInit() {
	staticData := &VbaLexerLexerStaticData
	staticData.once.Do(vbalexerLexerInit)
}

// NewvbaLexer produces a new lexer instance for the optional input antlr.CharStream.
func NewvbaLexer(input antlr.CharStream) *vbaLexer {
	VbaLexerInit()
	l := new(vbaLexer)
	l.BaseLexer = antlr.NewBaseLexer(input)
	staticData := &VbaLexerLexerStaticData
	l.Interpreter = antlr.NewLexerATNSimulator(l, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	l.channelNames = staticData.ChannelNames
	l.modeNames = staticData.ModeNames
	l.RuleNames = staticData.RuleNames
	l.LiteralNames = staticData.LiteralNames
	l.SymbolicNames = staticData.SymbolicNames
	l.GrammarFileName = "vba.g4"
	// TODO: l.EOF = antlr.TokenEOF

	return l
}

